import{_ as t,o as s,c as a,a5 as r}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse(`{"title":"00 — Vue d'ensemble produit","description":"","frontmatter":{},"headers":[],"relativePath":"specs/00-overview.md","filePath":"generated/specs/00-overview.md","lastUpdated":null}`),n={name:"specs/00-overview.md"};function i(o,e,l,d,c,u){return s(),a("div",null,[...e[0]||(e[0]=[r('<div><h1 id="_00-—-vue-d-ensemble-produit" tabindex="-1">00 — Vue d&#39;ensemble produit <a class="header-anchor" href="#_00-—-vue-d-ensemble-produit" aria-label="Permalink to &quot;00 — Vue d&#39;ensemble produit&quot;">​</a></h1><blockquote><p>Statut : fondation · Référence : <a href="/VendoraSystem-docs/produit/brainstorming"><code>../BRAINSTORMING.md</code></a> · Conventions : <a href="/VendoraSystem-docs/specs/index"><code>README.md</code></a></p><p>Ce document est la porte d&#39;entrée des spécifications. Il ne suit pas le template 11 sections (réservé aux specs fonctionnelles 01→16) : c&#39;est la vision produit, les personas, la carte des features et les parcours de référence.</p></blockquote><hr><h2 id="_1-vision-proposition-de-valeur" tabindex="-1">1. Vision &amp; proposition de valeur <a class="header-anchor" href="#_1-vision-proposition-de-valeur" aria-label="Permalink to &quot;1. Vision &amp; proposition de valeur&quot;">​</a></h2><p><strong>Un SaaS de point de vente capable de faire tourner n&#39;importe quel commerce — épicerie, boutique de vêtements, restaurant/café, pharmacie, services — avec un cœur commun et des modules activables, et qui ne s&#39;arrête jamais, même sans internet.</strong></p><p>Le marché des POS est fragmenté : des solutions verticales (restauration seule, retail seul), souvent dépendantes du cloud, chères à customiser, et opaques sur le stock (zone n°1 de fraude et d&#39;erreurs). Notre produit répond par trois différenciateurs structurants :</p><h3 id="_1-1-offline-first-sans-compromis" tabindex="-1">1.1 Offline-first, sans compromis <a class="header-anchor" href="#_1-1-offline-first-sans-compromis" aria-label="Permalink to &quot;1.1 Offline-first, sans compromis&quot;">​</a></h3><p>Rien ne doit jamais bloquer dans le magasin : <strong>vendre, encaisser, imprimer un ticket, envoyer une commande en cuisine fonctionnent sans internet.</strong> Chaque appareil embarque sa base locale (SQLite/SQLDelight) et un log d&#39;opérations append-only ; la synchronisation avec le cloud est opportuniste. Le temps réel intra-magasin (commande → cuisine, suivi des états) passe par un <strong>hub local</strong> sur le Wi-Fi du magasin (découverte mDNS, WebSocket local) : internet coupé = le restaurant tourne normalement. Le cloud n&#39;est autoritaire que pour la convergence et le multi-magasins. C&#39;est le pari technique n°1 du produit (voir <a href="/VendoraSystem-docs/specs/10-offline-sync">spec 10</a>) et son argument commercial n°1 face aux POS cloud-only.</p><h3 id="_1-2-multi-types-de-magasin-des-la-conception" tabindex="-1">1.2 Multi-types de magasin dès la conception <a class="header-anchor" href="#_1-2-multi-types-de-magasin-des-la-conception" aria-label="Permalink to &quot;1.2 Multi-types de magasin dès la conception&quot;">​</a></h3><p>Un seul produit, plusieurs métiers. Le commerçant choisit un <strong>profil</strong> (<code>GENERIC</code>, <code>GROCERY</code>, <code>APPAREL</code>, <code>RESTAURANT</code>, <code>SERVICE</code>) à la création du magasin ; ce profil active les bons <strong>modules</strong> (<code>tables</code>, <code>kitchen</code>, <code>variants</code>, <code>weight</code>, <code>expiry</code>, <code>appointments</code>…) et pré-configure l&#39;interface. Le cœur (vente, stock, clients, caisse, rapports) ne connaît pas les modules : il expose des points d&#39;extension (ligne de panier, fiche produit, flux d&#39;encaissement, routage de commande). Résultat : pas de fork par vertical, un seul code à maintenir, et un commerçant hybride (café + épicerie fine) active simplement les deux jeux de modules.</p><h3 id="_1-3-une-constellation-d-appareils-pas-«-une-caisse-»" tabindex="-1">1.3 Une constellation d&#39;appareils, pas « une caisse » <a class="header-anchor" href="#_1-3-une-constellation-d-appareils-pas-«-une-caisse-»" aria-label="Permalink to &quot;1.3 Une constellation d&#39;appareils, pas « une caisse »&quot;">​</a></h3><p>Le magasin n&#39;est pas un poste mais un <strong>écosystème d&#39;appareils enregistrés</strong>, chacun avec un rôle et des permissions :</p><table tabindex="0"><thead><tr><th>Rôle device</th><th>Appareil</th><th>Fait quoi</th></tr></thead><tbody><tr><td><code>REGISTER</code></td><td>PC/tablette + scanner + imprimante</td><td>Vente, encaissement, retours</td></tr><tr><td><code>KIOSK</code></td><td>Tablette verrouillée</td><td>Le client commande et paie seul</td></tr><tr><td><code>WAITER_TERMINAL</code></td><td>Téléphone du serveur</td><td>Prise de commande à la table</td></tr><tr><td><code>KDS</code></td><td>Tablette/écran en cuisine</td><td>Suivi et avancement des commandes</td></tr><tr><td><code>BACKOFFICE</code></td><td>Navigateur web</td><td>Catalogue, stock, rapports, configuration</td></tr></tbody></table><p>Un kiosque ne peut pas faire de retour ; un téléphone serveur ne peut pas ouvrir le tiroir-caisse. Les permissions sont portées par le device <strong>et</strong> par l&#39;utilisateur (<a href="/VendoraSystem-docs/specs/01-tenancy-auth">spec 01</a>).</p><h3 id="_1-4-piliers-transverses-non-negociables" tabindex="-1">1.4 Piliers transverses (non négociables) <a class="header-anchor" href="#_1-4-piliers-transverses-non-negociables" aria-label="Permalink to &quot;1.4 Piliers transverses (non négociables)&quot;">​</a></h3><ol><li><strong>Offline-first</strong> : toute fonctionnalité de vente marche sans internet.</li><li><strong>Append-only</strong> : stock et ventes sont des faits datés signés, jamais des états édités — le stock actuel se <em>recalcule</em>, il ne se « merge » pas.</li><li><strong>Traçabilité</strong> : toute action sensible → PIN manager + motif + <code>AuditLog</code> immuable.</li><li><strong>Performance</strong> : <strong>&lt; 100 ms</strong> par action caissier sur l&#39;écran de vente.</li><li><strong>Multi-tenant strict</strong> : isolation par <code>tenant_id</code> + Row-Level Security Postgres.</li></ol><hr><h2 id="_2-personas" tabindex="-1">2. Personas <a class="header-anchor" href="#_2-personas" aria-label="Permalink to &quot;2. Personas&quot;">​</a></h2><p>Les six personas du <a href="/VendoraSystem-docs/specs/index">README</a> sont la référence obligatoire des user stories de toutes les specs. Les voici développés.</p><h3 id="_2-1-omar-—-proprietaire-role-owner" tabindex="-1">2.1 Omar — propriétaire (rôle <code>OWNER</code>) <a class="header-anchor" href="#_2-1-omar-—-proprietaire-role-owner" aria-label="Permalink to &quot;2.1 Omar — propriétaire (rôle `OWNER`)&quot;">​</a></h3><ul><li><strong>Contexte</strong> : 52 ans, possède 2 épiceries dans deux quartiers différents. A démarré avec un cahier et une calculatrice ; utilise aujourd&#39;hui une caisse enregistreuse basique sans suivi de stock. Smartphone Android, pas très technique, délègue le quotidien à ses gérantes.</li><li><strong>Frustrations actuelles</strong> : il ne sait pas combien il gagne réellement par magasin ni par produit ; il soupçonne des pertes de stock (vol, casse, erreurs) sans pouvoir les prouver ; chaque fin de mois est une reconstitution manuelle ; quand il n&#39;est pas sur place, il est aveugle.</li><li><strong>Objectifs</strong> : voir les chiffres des deux magasins depuis son téléphone, détecter les écarts de caisse et les comportements anormaux (remises, annulations), dormir tranquille — tout est tracé, rien ne se perd sans explication. Il décide de l&#39;abonnement : le produit doit le rassurer en 10 minutes de démo.</li><li><strong>Specs clés</strong> : 12 (rapports &amp; anti-fraude), 14 (multi-magasins), 04 (écarts de caisse), 05 (traçabilité stock).</li></ul><h3 id="_2-2-lina-—-gerante-role-manager" tabindex="-1">2.2 Lina — gérante (rôle <code>MANAGER</code>) <a class="header-anchor" href="#_2-2-lina-—-gerante-role-manager" aria-label="Permalink to &quot;2.2 Lina — gérante (rôle `MANAGER`)&quot;">​</a></h3><ul><li><strong>Contexte</strong> : 34 ans, gère au quotidien l&#39;une des épiceries d&#39;Omar : équipe de 3 caissiers, commandes fournisseurs, réceptions, inventaires, prix. À l&#39;aise avec une tablette, pas le temps d&#39;apprendre un logiciel compliqué.</li><li><strong>Frustrations actuelles</strong> : ruptures découvertes au moment où un client demande le produit ; inventaires au papier-crayon qui prennent un dimanche entier ; dettes fournisseurs suivies dans un carnet ; aucun moyen simple de créer une étiquette pour un produit sans code-barres.</li><li><strong>Objectifs</strong> : être alertée avant la rupture, faire l&#39;inventaire au téléphone en scannant avec la caméra, réceptionner une livraison en 5 minutes (et que le stock se mette à jour tout seul), valider par PIN les actions sensibles de son équipe.</li><li><strong>Specs clés</strong> : 02 (catalogue &amp; étiquettes), 05 (stock &amp; inventaire), 07 (fournisseurs), 11 (matériel).</li></ul><h3 id="_2-3-karim-—-caissier-role-cashier" tabindex="-1">2.3 Karim — caissier (rôle <code>CASHIER</code>) <a class="header-anchor" href="#_2-3-karim-—-caissier-role-cashier" aria-label="Permalink to &quot;2.3 Karim — caissier (rôle `CASHIER`)&quot;">​</a></h3><ul><li><strong>Contexte</strong> : 23 ans, enchaîne les clients aux heures de pointe. Son outil de travail : la caisse (<code>REGISTER</code>), une douchette, une imprimante tickets.</li><li><strong>Frustrations actuelles</strong> (avec les POS qu&#39;il a connus) : écrans lents qui « ramment » quand il scanne vite, caisse inutilisable quand internet saute, produits sans code-barres qu&#39;il faut chercher dans des menus, pas de moyen propre d&#39;encaisser moitié espèces moitié carte.</li><li><strong>Objectifs</strong> : scanner-encaisser-suivant, <strong>&lt; 100 ms par action</strong>, boutons rapides pour le pain et les produits du quotidien, paiements multiples sans gymnastique, ouverture/clôture de session simple avec comptage guidé. Quand il a besoin d&#39;annuler une ligne ou de faire une grosse remise, il appelle le PIN de Lina — et c&#39;est normal.</li><li><strong>Specs clés</strong> : 03 (vente &amp; encaissement), 04 (sessions de caisse), 10 (offline), 11 (matériel).</li></ul><h3 id="_2-4-sami-—-serveur-role-waiter" tabindex="-1">2.4 Sami — serveur (rôle <code>WAITER</code>) <a class="header-anchor" href="#_2-4-sami-—-serveur-role-waiter" aria-label="Permalink to &quot;2.4 Sami — serveur (rôle `WAITER`)&quot;">​</a></h3><ul><li><strong>Contexte</strong> : 27 ans, travaille dans un café-restaurant de 20 tables. Prend les commandes sur son propre flux : salle bondée au service du midi.</li><li><strong>Frustrations actuelles</strong> : carnet papier → allers-retours en cuisine, erreurs de lecture du chef, oublis de lignes, additions reconstituées de tête, clients qui veulent « séparer l&#39;addition » en fin de repas.</li><li><strong>Objectifs</strong> : prendre la commande à la table sur son téléphone (<code>WAITER_TERMINAL</code>), qu&#39;elle parte <strong>instantanément</strong> en cuisine, être notifié quand c&#39;est prêt, garder l&#39;addition de la table ouverte, encaisser à la table ou renvoyer vers la caisse, partager l&#39;addition sans calcul mental.</li><li><strong>Specs clés</strong> : 08 (restaurant), 03 (encaissement), 10 (temps réel local).</li></ul><h3 id="_2-5-chef-nabil-—-cuisine-role-kitchen" tabindex="-1">2.5 Chef Nabil — cuisine (rôle <code>KITCHEN</code>) <a class="header-anchor" href="#_2-5-chef-nabil-—-cuisine-role-kitchen" aria-label="Permalink to &quot;2.5 Chef Nabil — cuisine (rôle `KITCHEN`)&quot;">​</a></h3><ul><li><strong>Contexte</strong> : 45 ans, tient la cuisine du même restaurant. Les mains occupées, pas le temps de toucher un écran plus de 2 secondes.</li><li><strong>Frustrations actuelles</strong> : bons de commande manuscrits illisibles, pas de priorisation (quelle table attend depuis le plus longtemps ?), personne en salle ne sait ce qui est prêt.</li><li><strong>Objectifs</strong> : voir les commandes arriver en temps réel sur le KDS (ou en bon imprimé ESC/POS — il préfère le papier pour le rush), faire avancer l&#39;état en un geste (<code>reçue → en préparation → prête → servie</code>), que la salle soit notifiée automatiquement. Et que ça marche même quand la box internet du restaurant plante — c&#39;est arrivé un samedi soir.</li><li><strong>Specs clés</strong> : 08 (restaurant/KDS), 11 (imprimante cuisine), 10 (hub local).</li></ul><h3 id="_2-6-la-cliente-finale" tabindex="-1">2.6 La cliente finale <a class="header-anchor" href="#_2-6-la-cliente-finale" aria-label="Permalink to &quot;2.6 La cliente finale&quot;">​</a></h3><ul><li><strong>Contexte</strong> : cliente régulière de l&#39;épicerie, ou cliente de passage au restaurant. Elle n&#39;est pas utilisatrice du système mais le subit ou en profite.</li><li><strong>Frustrations actuelles</strong> : files d&#39;attente, tickets papier perdus, cartes de fidélité en carton oubliées, « je paierai demain » noté nulle part.</li><li><strong>Objectifs</strong> : passer vite en caisse, recevoir son reçu en digital (QR sur le ticket, email/WhatsApp), cumuler des points identifiée par son numéro de téléphone ou un QR, utiliser son ardoise chez l&#39;épicier du quartier en toute confiance (plafond, historique), commander seule au kiosque du restaurant sans attendre un serveur.</li><li><strong>Specs clés</strong> : 06 (clients &amp; fidélité), 09 (kiosque), 13 (branding — elle voit « l&#39;app du commerçant », pas la nôtre).</li></ul><hr><h2 id="_3-carte-des-features-specs-01-→-16" tabindex="-1">3. Carte des features (specs 01 → 16) <a class="header-anchor" href="#_3-carte-des-features-specs-01-→-16" aria-label="Permalink to &quot;3. Carte des features (specs 01 → 16)&quot;">​</a></h2><h3 id="_01-—-tenancy-auth-devices-·-phase-0" tabindex="-1"><a href="/VendoraSystem-docs/specs/01-tenancy-auth">01 — Tenancy, auth &amp; devices</a> · Phase 0 <a class="header-anchor" href="#_01-—-tenancy-auth-devices-·-phase-0" aria-label="Permalink to &quot;[01 — Tenancy, auth &amp; devices](/specs/01-tenancy-auth) · Phase 0&quot;">​</a></h3><p>Le socle multi-tenant : comptes commerçants (<code>Tenant</code>), magasins (<code>Store</code>), utilisateurs avec rôles par magasin (<code>OWNER</code>→<code>KITCHEN</code>), et <strong>enregistrement des appareils</strong> avec rôle device et permissions. Auth JWT + refresh, actions sensibles sous PIN manager, RLS Postgres en filet de sécurité. <strong>Valeur</strong> : tout le reste s&#39;appuie dessus ; une fuite de données entre tenants serait fatale au SaaS — cette spec est le contrat d&#39;isolation.</p><h3 id="_02-—-catalogue-·-phases-0–1" tabindex="-1"><a href="/VendoraSystem-docs/specs/02-catalog">02 — Catalogue</a> · Phases 0–1 <a class="header-anchor" href="#_02-—-catalogue-·-phases-0–1" aria-label="Permalink to &quot;[02 — Catalogue](/specs/02-catalog) · Phases 0–1&quot;">​</a></h3><p>Produits, catégories, variantes (matrice taille × couleur pour <code>APPAREL</code>), prix achat/vente, TVA, codes-barres réels <strong>et générés</strong> (EAN-13 interne pour les produits sans code) + impression d&#39;étiquettes. <strong>Valeur</strong> : « tout produit devient scannable » — condition de la vitesse en caisse et de la fiabilité du stock ; le catalogue bien structuré est aussi ce qui rend les rapports utiles.</p><h3 id="_03-—-vente-encaissement-·-phase-1" tabindex="-1"><a href="/VendoraSystem-docs/specs/03-sales">03 — Vente &amp; encaissement</a> · Phase 1 <a class="header-anchor" href="#_03-—-vente-encaissement-·-phase-1" aria-label="Permalink to &quot;[03 — Vente &amp; encaissement](/specs/03-sales) · Phase 1&quot;">​</a></h3><p>Le cœur de la valeur : écran de vente ultra-rapide (douchette, caméra, boutons rapides), panier, remises (sous seuil → PIN), <strong>paiements multiples</strong> (espèces, carte, crédit client), tickets ESC/POS, retours tracés. Objectif &lt; 100 ms par action. <strong>Valeur</strong> : c&#39;est l&#39;écran où le commerçant passe sa journée ; sa fluidité décide de l&#39;adoption ou du rejet du produit.</p><h3 id="_04-—-sessions-de-caisse-·-phase-1" tabindex="-1"><a href="/VendoraSystem-docs/specs/04-cash-sessions">04 — Sessions de caisse</a> · Phase 1 <a class="header-anchor" href="#_04-—-sessions-de-caisse-·-phase-1" aria-label="Permalink to &quot;[04 — Sessions de caisse](/specs/04-cash-sessions) · Phase 1&quot;">​</a></h3><p>Ouverture avec fond de caisse, clôture avec comptage, <strong>écart calculé et tracé</strong>, rapport Z infalsifiable et numéroté. Chaque vente appartient à une session, un vendeur, un device. <strong>Valeur</strong> : la base de la confiance d&#39;Omar — l&#39;argent liquide est contrôlé, les écarts sont visibles, personne ne peut « refaire » une journée.</p><h3 id="_05-—-stock-inventaire-·-phases-1–3" tabindex="-1"><a href="/VendoraSystem-docs/specs/05-inventory">05 — Stock &amp; inventaire</a> · Phases 1–3 <a class="header-anchor" href="#_05-—-stock-inventaire-·-phases-1–3" aria-label="Permalink to &quot;[05 — Stock &amp; inventaire](/specs/05-inventory) · Phases 1–3&quot;">​</a></h3><p>Le stock comme <strong>somme de mouvements signés</strong> (<code>StockMovement</code> append-only) : jamais de « set quantité », uniquement des ajustements motivés (inventaire, casse, perte, vol, erreur). Inventaires au mobile avec scan caméra, écarts théorique/réel, validation manager, alertes anti-fraude. <strong>Valeur</strong> : « tout passe par le système, rien ne se perd, tout s&#39;explique » — le différenciateur face à la fraude, zone n°1 de pertes du commerce.</p><h3 id="_06-—-clients-fidelite-·-phase-3" tabindex="-1"><a href="/VendoraSystem-docs/specs/06-customers-loyalty">06 — Clients &amp; fidélité</a> · Phase 3 <a class="header-anchor" href="#_06-—-clients-fidelite-·-phase-3" aria-label="Permalink to &quot;[06 — Clients &amp; fidélité](/specs/06-customers-loyalty) · Phase 3&quot;">​</a></h3><p>Fiches clients, points de fidélité avec paliers/récompenses, identification rapide en caisse (téléphone, carte, QR), <strong>ardoise</strong> (crédit client plafonné, règlement partiel, rappels), reçus digitaux (QR/email/SMS/WhatsApp). <strong>Valeur</strong> : l&#39;ardoise est très demandée dans les petits commerces et quasi absente des POS classiques ; la fidélité fait revenir la cliente finale.</p><h3 id="_07-—-fournisseurs-achats-·-phase-3" tabindex="-1"><a href="/VendoraSystem-docs/specs/07-suppliers">07 — Fournisseurs &amp; achats</a> · Phase 3 <a class="header-anchor" href="#_07-—-fournisseurs-achats-·-phase-3" aria-label="Permalink to &quot;[07 — Fournisseurs &amp; achats](/specs/07-suppliers) · Phase 3&quot;">​</a></h3><p>Fiches fournisseurs, bons de commande, <strong>réceptions qui génèrent les mouvements de stock</strong>, dettes fournisseurs et échéances. <strong>Valeur</strong> : boucle complète achat → stock → vente → marge ; Lina sort du carnet papier. L&#39;annuaire/marketplace fournisseurs est noté comme piste ultérieure (hors v1 du périmètre spec).</p><h3 id="_08-—-restaurant-·-phase-2" tabindex="-1"><a href="/VendoraSystem-docs/specs/08-restaurant">08 — Restaurant</a> · Phase 2 <a class="header-anchor" href="#_08-—-restaurant-·-phase-2" aria-label="Permalink to &quot;[08 — Restaurant](/specs/08-restaurant) · Phase 2&quot;">​</a></h3><p>Le module vertical le plus riche : plan de salle et tables, additions ouvertes et partagées, app serveur (<code>WAITER_TERMINAL</code>), <strong>KDS</strong> et/ou imprimante cuisine, états de commande (<code>reçue → en préparation → prête → servie</code>) en temps réel — <strong>sur le réseau local</strong>, internet ou pas. <strong>Valeur</strong> : le flux commande → cuisine → service → encaissement est le cœur battant d&#39;un restaurant ; le faire tourner offline est un argument décisif.</p><h3 id="_09-—-kiosque-self-service-·-phase-4" tabindex="-1"><a href="/VendoraSystem-docs/specs/09-kiosk">09 — Kiosque self-service</a> · Phase 4 <a class="header-anchor" href="#_09-—-kiosque-self-service-·-phase-4" aria-label="Permalink to &quot;[09 — Kiosque self-service](/specs/09-kiosk) · Phase 4&quot;">​</a></h3><p>Tablette en mode verrouillé où le client commande et paie seul : scan caméra, UI simplifiée et <strong>brandée aux couleurs du commerçant</strong>, permissions réduites (pas de retour, pas de tiroir). <strong>Valeur</strong> : désengorge la caisse et les serveurs, augmente le panier moyen, et le branding donne au commerçant « son » application.</p><h3 id="_10-—-offline-synchronisation-·-phases-0–1" tabindex="-1"><a href="/VendoraSystem-docs/specs/10-offline-sync">10 — Offline &amp; synchronisation</a> · Phases 0–1 <a class="header-anchor" href="#_10-—-offline-synchronisation-·-phases-0–1" aria-label="Permalink to &quot;[10 — Offline &amp; synchronisation](/specs/10-offline-sync) · Phases 0–1&quot;">​</a></h3><p>Le socle technique différenciant : base locale par appareil, <strong>log d&#39;opérations append-only</strong> (événements au passé : <code>SaleCompleted</code>, <code>OrderPlaced</code>…), UUID côté client, serveur cloud autoritaire pour la convergence, stock recalculé depuis les mouvements (conflits quasi inexistants), <strong>hub local</strong> mDNS + WebSocket pour le temps réel intra-magasin. <strong>Valeur</strong> : c&#39;est le risque technique n°1, dérisqué en phase 0 par un POC — et la promesse n°1 du produit.</p><h3 id="_11-—-materiel-·-phase-1" tabindex="-1"><a href="/VendoraSystem-docs/specs/11-hardware">11 — Matériel</a> · Phase 1 <a class="header-anchor" href="#_11-—-materiel-·-phase-1" aria-label="Permalink to &quot;[11 — Matériel](/specs/11-hardware) · Phase 1&quot;">​</a></h3><p>Imprimantes tickets ESC/POS (réseau/Bluetooth en direct depuis mobile, agent d&#39;impression local pour le web), douchettes en émulation clavier (zéro driver), scan caméra, tiroir-caisse piloté par l&#39;imprimante (ouverture tracée), étiqueteuses. <strong>Valeur</strong> : un POS qui n&#39;imprime pas n&#39;existe pas ; la compatibilité matérielle large réduit le coût d&#39;entrée du commerçant qui garde son équipement.</p><h3 id="_12-—-rapports-tableau-de-bord-·-phase-3" tabindex="-1"><a href="/VendoraSystem-docs/specs/12-reports">12 — Rapports &amp; tableau de bord</a> · Phase 3 <a class="header-anchor" href="#_12-—-rapports-tableau-de-bord-·-phase-3" aria-label="Permalink to &quot;[12 — Rapports &amp; tableau de bord](/specs/12-reports) · Phase 3&quot;">​</a></h3><p>Rapports de vente, marges par produit/catégorie, dashboard du gérant et du propriétaire, et <strong>alertes anti-fraude</strong> : écarts de caisse récurrents par caissier/poste, remises anormales, annulations fréquentes. <strong>Valeur</strong> : c&#39;est ce qu&#39;Omar regarde chaque soir ; les données signées des specs 03/04/05 deviennent ici des décisions.</p><h3 id="_13-—-customisation-white-label-·-phase-4" tabindex="-1"><a href="/VendoraSystem-docs/specs/13-customization">13 — Customisation &amp; white-label</a> · Phase 4 <a class="header-anchor" href="#_13-—-customisation-white-label-·-phase-4" aria-label="Permalink to &quot;[13 — Customisation &amp; white-label](/specs/13-customization) · Phase 4&quot;">​</a></h3><p>Moteur de thèmes par magasin : couleurs, logo (app + tickets + reçus digitaux), nom affiché, écrans configurables (boutons rapides, catégories mises en avant, langue), configuration par device. <strong>Valeur</strong> : l&#39;UI s&#39;adapte au métier (un kiosque restaurant ≠ une caisse épicerie) et le commerçant présente « son » application à ses clients.</p><h3 id="_14-—-multi-magasins-·-phase-3" tabindex="-1"><a href="/VendoraSystem-docs/specs/14-multi-store">14 — Multi-magasins</a> · Phase 3 <a class="header-anchor" href="#_14-—-multi-magasins-·-phase-3" aria-label="Permalink to &quot;[14 — Multi-magasins](/specs/14-multi-store) · Phase 3&quot;">​</a></h3><p>Plusieurs magasins sous un même tenant : <strong>transferts de stock</strong> (mouvements signés des deux côtés), consolidation des rapports, gestion centralisée du catalogue avec surcharges locales (prix par magasin). <strong>Valeur</strong> : la raison pour laquelle Omar, 2 épiceries, choisit un SaaS plutôt qu&#39;une caisse isolée — et le levier d&#39;upsell naturel du modèle économique.</p><h3 id="_15-—-conformite-fiscale-module-par-pays-·-phases-1–2" tabindex="-1">15 — Conformité fiscale (module par pays) · Phases 1–2 <a class="header-anchor" href="#_15-—-conformite-fiscale-module-par-pays-·-phases-1–2" aria-label="Permalink to &quot;15 — Conformité fiscale (module par pays) · Phases 1–2&quot;">​</a></h3><p>Module fiscal activable selon le pays du magasin : <strong>signature chaînée</strong> des événements de vente, clôtures journalières/mensuelles/annuelles avec totaux perpétuels, exigences <strong>NF525/LNE</strong> pour la France, <strong>NACEF</strong> pour la Tunisie (QR fiscal sur le ticket, transmission temps réel à l&#39;administration), archivage légal. <strong>Valeur</strong> : condition d&#39;accès au marché — sans homologation NACEF, pas de go-to-market restauration en Tunisie ; sans certification NF525/LNE, pas de commercialisation en France. L&#39;architecture append-only et le rapport Z infalsifiable (specs 03/04/10) en sont le socle naturel.</p><h3 id="_16-—-canaux-clients-·-phase-4" tabindex="-1">16 — Canaux clients · Phase 4 <a class="header-anchor" href="#_16-—-canaux-clients-·-phase-4" aria-label="Permalink to &quot;16 — Canaux clients · Phase 4&quot;">​</a></h3><p>Les canaux de commande côté client, au-delà du comptoir : <strong>menu QR à table</strong> (consulter et commander depuis son téléphone), <strong>commande en ligne</strong> et <strong>click &amp; collect</strong>. Les commandes entrent dans le même flux que la salle et le kiosque (specs 08/09) : routage cuisine, états, encaissement. <strong>Valeur</strong> : le restaurant capte des commandes sans mobiliser un serveur ni un kiosque, et le commerçant offre le retrait sans dépendre d&#39;une plateforme tierce — aux couleurs de son enseigne.</p><hr><h2 id="_4-matrice-modules-×-profils-de-magasin" tabindex="-1">4. Matrice modules × profils de magasin <a class="header-anchor" href="#_4-matrice-modules-×-profils-de-magasin" aria-label="Permalink to &quot;4. Matrice modules × profils de magasin&quot;">​</a></h2><p>Modules actifs <strong>par défaut</strong> à la création du magasin selon le profil. Tout module reste activable/désactivable manuellement ensuite (un café-épicerie active <code>weight</code> ; une boutique sans fidélité coupe <code>loyalty</code>).</p><table tabindex="0"><thead><tr><th>Module</th><th style="text-align:center;">GENERIC</th><th style="text-align:center;">GROCERY</th><th style="text-align:center;">APPAREL</th><th style="text-align:center;">RESTAURANT</th><th style="text-align:center;">SERVICE</th></tr></thead><tbody><tr><td><code>tables</code> (plan de salle, additions ouvertes)</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td></tr><tr><td><code>kitchen</code> (routage cuisine, KDS, états)</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td></tr><tr><td><code>kiosk</code> (self-service verrouillé)</td><td style="text-align:center;">⬜</td><td style="text-align:center;">⬜</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td></tr><tr><td><code>variants</code> (matrice taille × couleur)</td><td style="text-align:center;">⬜</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><code>weight</code> (vente au poids, balance)</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><code>expiry</code> (péremption, lots)</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">⬜</td><td style="text-align:center;">—</td></tr><tr><td><code>appointments</code> (rendez-vous, prestations)</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td><code>customer-credit</code> (ardoise)</td><td style="text-align:center;">⬜</td><td style="text-align:center;">✅</td><td style="text-align:center;">⬜</td><td style="text-align:center;">⬜</td><td style="text-align:center;">✅</td></tr><tr><td><code>loyalty</code> (points, récompenses)</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><code>online-ordering</code> (menu QR, commande en ligne, click &amp; collect)</td><td style="text-align:center;">⬜</td><td style="text-align:center;">⬜</td><td style="text-align:center;">⬜</td><td style="text-align:center;">✅</td><td style="text-align:center;">⬜</td></tr></tbody></table><p>Légende : ✅ actif par défaut · ⬜ disponible, désactivé par défaut · — non proposé par défaut (activable sur demande).</p><p>Le <strong>cœur commun</strong> (catalogue, vente, paiements, sessions de caisse, stock, clients, rapports, offline/sync, devices) est présent dans tous les profils et ne se désactive pas. Nuance par profil : <code>SERVICE</code> a le suivi de stock optionnel par produit (prestations sans stock) ; <code>RESTAURANT</code> vend surtout par boutons rapides plutôt qu&#39;au scan.</p><hr><h2 id="_5-parcours-types-end-to-end" tabindex="-1">5. Parcours types end-to-end <a class="header-anchor" href="#_5-parcours-types-end-to-end" aria-label="Permalink to &quot;5. Parcours types end-to-end&quot;">​</a></h2><p>Trois journées de référence qui servent de fil rouge aux specs et aux tests d&#39;acceptation. Chaque étape cite la spec qui la couvre.</p><h3 id="_5-1-journee-type-d-une-epicerie-grocery-—-lina-karim" tabindex="-1">5.1 Journée type d&#39;une épicerie (<code>GROCERY</code>) — Lina &amp; Karim <a class="header-anchor" href="#_5-1-journee-type-d-une-epicerie-grocery-—-lina-karim" aria-label="Permalink to &quot;5.1 Journée type d&#39;une épicerie (`GROCERY`) — Lina &amp; Karim&quot;">​</a></h3><ol><li><strong>07h30 — Ouverture.</strong> Karim se connecte sur la caisse, ouvre une session avec un fond de caisse de 200,00 (compté, saisi en centimes) → <code>CashSessionOpened</code> [04].</li><li><strong>08h00 — Réception fournisseur.</strong> Lina réceptionne la livraison du grossiste sur la tablette : elle scanne les produits, confirme les quantités contre le bon de commande ; chaque ligne génère un <code>StockMovementRecorded</code> de type réception ; la dette fournisseur est mise à jour [07, 05].</li><li><strong>08h15 — Nouveau produit.</strong> Un article artisanal sans code-barres : Lina crée la fiche, le système génère un EAN-13 interne, elle imprime 20 étiquettes [02, 11].</li><li><strong>09h00–13h00 — Rush du matin.</strong> Karim scanne à la douchette, vend le pain au bouton rapide, pèse les tomates (module <code>weight</code>), encaisse espèces/carte, parfois les deux sur un même ticket. Une cliente régulière donne son numéro de téléphone : points de fidélité crédités ; une autre « met sur l&#39;ardoise » (plafond vérifié) [03, 06].</li><li><strong>11h20 — Coupure internet.</strong> La fibre saute 40 minutes. <strong>Rien ne change en caisse</strong> : ventes, tickets, fidélité locale continuent ; les événements s&#39;empilent dans le log local et se synchronisent au retour du réseau [10].</li><li><strong>14h00 — Action sensible.</strong> Karim doit annuler une ligne déjà scannée (erreur de quantité) : PIN de Lina + motif, l&#39;action part dans l&#39;<code>AuditLog</code> [03, 01].</li><li><strong>17h00 — Mini-inventaire tournant.</strong> Lina compte le rayon boissons au téléphone, scan caméra ; le système affiche les écarts théorique/réel ; elle valide → ajustements motivés générés [05].</li><li><strong>20h00 — Clôture.</strong> Karim compte la caisse, saisit le comptage ; écart de −3,50 calculé et tracé ; rapport Z numéroté émis → <code>CashSessionClosed</code> [04].</li><li><strong>21h00 — Omar, chez lui.</strong> Il ouvre le dashboard : CA des 2 magasins, marges, écart de caisse du jour, aucune alerte anti-fraude. Il se couche tranquille [12, 14].</li></ol><h3 id="_5-2-service-du-midi-d-un-restaurant-restaurant-—-sami-chef-nabil" tabindex="-1">5.2 Service du midi d&#39;un restaurant (<code>RESTAURANT</code>) — Sami &amp; Chef Nabil <a class="header-anchor" href="#_5-2-service-du-midi-d-un-restaurant-restaurant-—-sami-chef-nabil" aria-label="Permalink to &quot;5.2 Service du midi d&#39;un restaurant (`RESTAURANT`) — Sami &amp; Chef Nabil&quot;">​</a></h3><ol><li><strong>11h30 — Mise en place.</strong> Le gérant ouvre la session de caisse ; les devices du restaurant (caisse, 2 téléphones serveurs, KDS, imprimante cuisine) sont connectés au hub local sur le Wi-Fi [04, 10, 01].</li><li><strong>12h05 — Table 5.</strong> Sami prend la commande sur son téléphone : 2 plats du jour, 1 salade sans oignons (note de ligne), 3 boissons → <code>OrderPlaced</code>. <strong>Instantanément</strong>, le bon s&#39;imprime en cuisine et la commande apparaît sur le KDS [08, 11].</li><li><strong>12h10 — En parallèle, kiosque.</strong> Un client pressé commande deux sandwichs à emporter au kiosque et paie par carte ; la commande part en cuisine avec le marqueur « à emporter » [09, 08].</li><li><strong>12h15 — Cuisine.</strong> Nabil passe la table 5 <code>en préparation</code> puis <code>prête</code> → <code>OrderStatusChanged</code> ; le téléphone de Sami est notifié [08].</li><li><strong>12h20 — Incident réseau.</strong> La box internet tombe en plein rush. Le hub local relaie : les commandes continuent de partir en cuisine, les états continuent de circuler. Personne en salle ne s&#39;en aperçoit [10].</li><li><strong>12h40 — Table 5, suite.</strong> Les clients commandent des desserts : l&#39;addition de la table reste <strong>ouverte</strong>, les nouvelles lignes partent en cuisine [08].</li><li><strong>13h15 — Encaissement.</strong> La table 5 veut partager : 2 parts égales sur les boissons, chacun ses plats. Sami partage l&#39;addition sur son téléphone et encaisse à la table (1 carte, 1 espèces rendu monnaie à la caisse) ; l&#39;<code>Order</code> devient une <code>Sale</code> rattachée à la session [08, 03].</li><li><strong>15h00 — Fin de service.</strong> Le gérant consulte le récap du service : tickets moyens, temps de préparation par plat, ventes kiosque vs salle [12].</li></ol><h3 id="_5-3-vente-en-boutique-de-vetements-apparel" tabindex="-1">5.3 Vente en boutique de vêtements (<code>APPAREL</code>) <a class="header-anchor" href="#_5-3-vente-en-boutique-de-vetements-apparel" aria-label="Permalink to &quot;5.3 Vente en boutique de vêtements (`APPAREL`)&quot;">​</a></h3><ol><li><strong>10h00 — Ouverture.</strong> La vendeuse ouvre sa session de caisse [04].</li><li><strong>10h30 — Conseil &amp; variantes.</strong> Une cliente veut une chemise vue en vitrine. La vendeuse scanne l&#39;étiquette : fiche produit avec <strong>matrice taille × couleur</strong> et stock par variante — le M bleu est épuisé ici, mais la boutique du centre-ville en a 2 (visibilité multi-magasins) [02, 14].</li><li><strong>11h00 — Vente.</strong> La cliente prend le L bleu et un pantalon en promo (remise catalogue, pas de PIN nécessaire). Identification fidélité par QR ; paiement carte ; reçu digital envoyé par email — aux couleurs de la boutique [03, 06, 13].</li><li><strong>14h00 — Retour.</strong> Un client rapporte un article de la veille, ticket en main : retour tracé (motif), remboursement sur le moyen de paiement d&#39;origine, <code>StockMovementRecorded</code> de type retour réintègre la variante exacte, PIN manager requis [03, 05].</li><li><strong>16h00 — Transfert.</strong> La gérante demande le transfert de 2 chemises M bleu depuis l&#39;autre boutique : mouvement de sortie signé là-bas, mouvement d&#39;entrée signé ici à réception [14, 05].</li><li><strong>19h00 — Clôture &amp; analyse.</strong> Rapport Z, puis coup d&#39;œil au dashboard : top ventes par variante — le bleu surperforme, réassort à prévoir [04, 12].</li></ol><hr><h2 id="_6-kpis-produit" tabindex="-1">6. KPIs produit <a class="header-anchor" href="#_6-kpis-produit" aria-label="Permalink to &quot;6. KPIs produit&quot;">​</a></h2><h3 id="_6-1-performance-promesse-«-lt-100-ms-»" tabindex="-1">6.1 Performance (promesse « &lt; 100 ms ») <a class="header-anchor" href="#_6-1-performance-promesse-«-lt-100-ms-»" aria-label="Permalink to &quot;6.1 Performance (promesse « &amp;lt; 100 ms »)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>KPI</th><th>Cible</th><th>Mesure</th></tr></thead><tbody><tr><td>Latence par action caissier (scan → ligne affichée, tap bouton rapide, ajout paiement)</td><td><strong>p95 &lt; 100 ms</strong></td><td>instrumentation in-app, sur matériel milieu de gamme</td></tr><tr><td>Scan douchette → ligne de panier</td><td>p95 &lt; 100 ms</td><td>idem</td></tr><tr><td>Commande envoyée → affichage KDS / impression cuisine (réseau local)</td><td>p95 &lt; 2 s</td><td>horodatage des événements du hub local</td></tr><tr><td>Démarrage à froid de l&#39;app caisse → prêt à vendre</td><td>&lt; 5 s</td><td>mesure de lancement</td></tr></tbody></table><blockquote><p><strong>Mesure en production (lot 2.27, 30/10/2026)</strong> — chaque caisse mesure ses actions (<code>ActionLatencyRecorder</code>, p50 / p95 / max par action, fenêtre glissante) et envoie l&#39;instantané au serveur <strong>après chaque pull réussi</strong> (<code>POST /api/v1/pos/telemetry/latency</code>, jeton d&#39;appareil, aucune donnée métier), puis vide sa fenêtre. Le back-office affiche <strong>« Latence des caisses »</strong> : dernier rapport par appareil et action, p95 contre le budget de 100 ms (<code>GET /api/v1/stores/{id}/telemetry/latency</code>, MANAGER+).</p></blockquote><h3 id="_6-2-fiabilite-offline-promesse-«-rien-ne-bloque-jamais-»" tabindex="-1">6.2 Fiabilité offline (promesse « rien ne bloque jamais ») <a class="header-anchor" href="#_6-2-fiabilite-offline-promesse-«-rien-ne-bloque-jamais-»" aria-label="Permalink to &quot;6.2 Fiabilité offline (promesse « rien ne bloque jamais »)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>KPI</th><th>Cible</th></tr></thead><tbody><tr><td>Fonctionnalités de vente disponibles sans internet</td><td><strong>100 %</strong> (vendre, encaisser, imprimer, envoyer en cuisine)</td></tr><tr><td>Perte d&#39;événements (vente/commande/mouvement acceptés localement puis perdus)</td><td><strong>0</strong> — critère absolu</td></tr><tr><td>Convergence après retour du réseau (sync complète d&#39;une journée offline)</td><td>&lt; 60 s</td></tr><tr><td>Divergence de stock après re-calcul serveur vs local</td><td>0 (même moteur de calcul KMP partagé)</td></tr><tr><td>Bascule cloud ↔ hub local</td><td>automatique, sans action utilisateur</td></tr></tbody></table><h3 id="_6-3-adoption-activation" tabindex="-1">6.3 Adoption &amp; activation <a class="header-anchor" href="#_6-3-adoption-activation" aria-label="Permalink to &quot;6.3 Adoption &amp; activation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>KPI</th><th>Cible</th></tr></thead><tbody><tr><td>Onboarding : création du magasin → première vente réelle</td><td>&lt; 1 jour (cible : &lt; 2 h avec catalogue importé)</td></tr><tr><td>Taux d&#39;activation des sessions de caisse (ouverture/clôture utilisées quotidiennement)</td><td>&gt; 90 % des magasins actifs</td></tr><tr><td>Part des ventes passant par le système (vs « à côté »)</td><td>tend vers 100 % — proxy : régularité des rapports Z</td></tr><tr><td>Rétention tenant à 3 mois</td><td>&gt; 85 %</td></tr><tr><td>Adoption des devices secondaires (serveur, KDS, kiosque) chez les restaurants</td><td>&gt; 60 % des tenants <code>RESTAURANT</code> avec ≥ 2 rôles de devices</td></tr><tr><td>NPS commerçants</td><td>&gt; 40</td></tr></tbody></table><h3 id="_6-4-confiance-integrite" tabindex="-1">6.4 Confiance &amp; intégrité <a class="header-anchor" href="#_6-4-confiance-integrite" aria-label="Permalink to &quot;6.4 Confiance &amp; intégrité&quot;">​</a></h3><table tabindex="0"><thead><tr><th>KPI</th><th>Cible</th></tr></thead><tbody><tr><td>Actions sensibles sans trace d&#39;audit</td><td>0 (vérifié par tests d&#39;intégrité)</td></tr><tr><td>Fuite de données inter-tenants</td><td>0 — testé en continu (RLS + tests d&#39;isolation)</td></tr><tr><td>Écart de caisse moyen par magasin</td><td>en baisse après 1 mois d&#39;usage (indicateur de valeur anti-fraude)</td></tr></tbody></table><hr><h2 id="_7-hors-perimetre-v1" tabindex="-1">7. Hors périmètre v1 <a class="header-anchor" href="#_7-hors-perimetre-v1" aria-label="Permalink to &quot;7. Hors périmètre v1&quot;">​</a></h2><p>Explicitement <strong>exclus</strong> de la v1 — soit reportés à une phase ultérieure, soit non prévus. Toute spec qui semblerait en avoir besoin doit le signaler plutôt que l&#39;implémenter.</p><table tabindex="0"><thead><tr><th>Hors périmètre</th><th>Statut</th><th>Notes</th></tr></thead><tbody><tr><td><strong>E-commerce / boutique en ligne</strong></td><td>non prévu v1</td><td>Le POS gère le magasin physique ; pas de vitrine web généraliste. La commande en ligne et le click &amp; collect sont désormais couverts par la <strong>spec 16 — Canaux clients</strong> (phase 4). API publique en phase 4 comme porte d&#39;entrée future.</td></tr><tr><td><strong>Comptabilité complète</strong></td><td>non prévu v1</td><td>Pas de grand livre, de bilan ni de déclarations fiscales. Le produit fournit les rapports (Z, ventes, TVA collectée) <strong>et les exports comptables + FEC</strong> (spec 12) ; la tenue de comptabilité elle-même reste chez l&#39;expert-comptable.</td></tr><tr><td><strong>Paie &amp; planning RH</strong></td><td>non prévu</td><td>Rôles et sessions servent la traçabilité, pas la gestion des salaires, congés ou plannings d&#39;équipe.</td></tr><tr><td><strong>Livraison / plateformes (Uber Eats, Glovo…)</strong></td><td>non prévu v1</td><td>Pas d&#39;intégration de canaux de livraison ni de gestion de livreurs.</td></tr><tr><td><strong>Marketplace / annuaire fournisseurs</strong></td><td>reporté (post-v1, cf. phase 4+)</td><td>Idée différenciante actée au brainstorming mais la v1 se limite à la gestion interne des fournisseurs (spec 07).</td></tr><tr><td><strong>Promotions ciblées / campagnes marketing</strong></td><td>reporté</td><td>L&#39;historique d&#39;achats (spec 06) en est la base ; les campagnes (SMS/emailing ciblé) viendront après.</td></tr><tr><td><strong>Balance connectée &amp; afficheur client</strong></td><td>reporté (phase ultérieure, cf. brainstorming §5.5)</td><td>Le module <code>weight</code> v1 accepte la saisie manuelle du poids.</td></tr><tr><td><strong>Certification fiscale (NF525 &amp; équivalents)</strong></td><td>⚠ désormais DANS le périmètre</td><td>La conformité fiscale FR/TN (NF525/LNE, NACEF) est couverte par la <strong>spec 15 — Conformité fiscale</strong> (module par pays, phases 1–2) : signature chaînée, clôtures, QR fiscal, archivage. Ne figure plus hors périmètre.</td></tr><tr><td><strong>Paiement intégré au kiosque (Stripe Terminal, SumUp…)</strong></td><td>à l&#39;étude, dépend du pays</td><td>Le kiosque v1 peut fonctionner en « commander au kiosque, payer en caisse » si l&#39;intégration n&#39;est pas prête.</td></tr><tr><td><strong>Offline du back-office web</strong></td><td>non prévu</td><td>Décision actée : le web ne fait pas de vente, il n&#39;a pas besoin d&#39;offline.</td></tr><tr><td><strong>Multi-devise par magasin</strong></td><td>non prévu v1</td><td>Une devise par magasin (ISO 4217) ; pas de conversion.</td></tr><tr><td><strong>Application cliente finale (app de fidélité)</strong></td><td>non prévu v1</td><td>La cliente est identifiée en caisse (téléphone, carte, QR) ; pas d&#39;app dédiée à télécharger.</td></tr></tbody></table><hr><p><em>Prochaine étape : les specs 01 (tenancy/auth/devices) et 10 (offline &amp; sync) sont les fondations de la phase 0 — à rédiger en premier, le POC sync/hub local étant le risque n°1 à dérisquer.</em></p></div>',1)])])}const h=t(n,[["render",i]]);export{m as __pageData,h as default};
